INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a46fd925-ce5c-59d7-9bff-0fef4b5ca214', 'Sweden Swedish Climate Policy Framework', 'The Swedish Climate Policy Framework', 'In 2017, Sweden’s Riksdag decided by a large political majority to introduce a climate policy framework with a climate act for Sweden. This framework is the most important climate reform in Sweden’s history and sets out implementation of the Paris Agreement in Sweden. By 2045, Sweden is to have zero net emissions of greenhouse gases into the atmosphere.', 'In 2017, Sweden’s Riksdag decided by a large political majority to introduce a climate policy framework with a climate act for Sweden. This framework is the most important climate reform in Sweden’s history and sets out implementation of the Paris Agreement in Sweden. By 2045, Sweden is to have zero net emissions of greenhouse gases into the atmosphere.', 'In 2017, Sweden’s Riksdag decided by a large political majority to introduce a climate policy framework with a climate act for Sweden. This framework is the most important climate reform in Sweden’s history and sets out implementation of the Paris Agreement in Sweden. By 2045, Sweden is to have zero net emissions of greenhouse gases into the atmosphere.', 'Sweden', 'climate', 'in_force', '2017-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_13', ARRAY['sdg13', 'voluntary_frameworks', 'other sustainability policy', 'sweden', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('621fb2b4-fbcc-526e-a79a-c9402eba86d0', 'Sweden Swedish Corporate Governance Code', 'The Swedish Corporate Governance Code, 2017', 'The memorandum proposes changes to the investment rules in the Act (2000:192) on general pension funds (AP funds). The purpose of the changes is to streamline the investment rules to provide better conditions for the First–Fourth AP funds to be able to achieve the goal of management, to maximize the long-term return in relation to the risk in the investments, especially in the prevailing low interest rate environment. The proposal means that the minimum percentage of interest-bearing securities with low credit and liquidity risk is reduced from 30 to 20 percent, that the restriction on unlisted securities is removed and replaced by a maximum proportion of illiquid assets, and that the requirement for external management is removed. However, the changes mean a continued limited freedom of action in comparison with the transition to a so-called precautionary principle that was proposed in the ministry''s memorandum New rules for the AP funds (Ds 2015:34).', 'The memorandum proposes changes to the investment rules in the Act (2000:192) on general pension funds (AP funds). The purpose of the changes is to streamline the investment rules to provide better conditions for the First–Fourth AP funds to be able to achieve the goal of management, to maximize the long-term return in relation to the risk in the investments, especially in the prevailing low interest rate environment. The proposal means that the minimum percentage of interest-bearing securities with low credit and liquidity risk is reduced from 30 to 20 percent, that the restriction on unlisted securities is removed and replaced by a maximum proportion of illiquid assets, and that the requirement for external management is removed. However, the changes mean a continued limited freedom of action in comparison with the transition to a so-called precautionary principle that was proposed in the ministry''s memorandum New rules for the AP funds (Ds 2015:34).', 'The memorandum proposes changes to the investment rules in the Act (2000:192) on general pension funds (AP funds). The purpose of the changes is to streamline the investment rules to provide better conditions for the First–Fourth AP funds to be able to achieve the goal of management, to maximize the long-term return in relation to the risk in the investments, especially in the prevailing low interest rate environment. The proposal means that the minimum percentage of interest-bearing securities with low credit and liquidity risk is reduced from 30 to 20 percent, that the restriction on unlisted securities is removed and replaced by a maximum proportion of illiquid assets, and that the requirement for external management is removed. However, the changes mean a continued limited freedom of action in comparison with the transition to a so-called precautionary principle that was proposed in the ministry''s memorandum New rules for the AP funds (Ds 2015:34).', 'Sweden', 'climate', 'in_force', '2017-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_6', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6bfbfbcd-cf4a-5862-b5fa-e0276c1346cb', 'Sweden Swedish Corporate Governance Code', 'The Swedish Corporate Governance Code', 'The Swedish Corporate Governance Code, updated and effective as of December 1, 2016, establishes a framework for good corporate governance practices in listed companies on regulated markets in Sweden. It aims to foster trust in Swedish companies by promoting transparency, accountability, and long-term value creation while maintaining flexibility through the "comply or explain" principle. Companies must disclose adherence to the Code’s provisions or provide explanations for deviations, ensuring that alternative approaches are transparent and well-justified.

The Code emphasizes the responsibilities of shareholders, boards of directors, and management in achieving effective governance. It covers key areas such as board composition, nomination processes, the division of roles between boards and executives, risk management, remuneration policies, and sustainability reporting. Specific provisions mandate the establishment of nomination committees, annual evaluations of boards and CEOs, and clear rules on information disclosure and remuneration. The Code also incorporates requirements from EU directives, including shareholder rights and non-financial information disclosure.

By aligning with international governance standards and EU regulations, the Code supports harmonization within Nordic and European markets. It enhances investor confidence, competitiveness, and the sustainable development of Swedish-listed companies.', 'The Swedish Corporate Governance Code, updated and effective as of December 1, 2016, establishes a framework for good corporate governance practices in listed companies on regulated markets in Sweden. It aims to foster trust in Swedish companies by promoting transparency, accountability, and long-term value creation while maintaining flexibility through the "comply or explain" principle. Companies must disclose adherence to the Code’s provisions or provide explanations for deviations, ensuring that alternative approaches are transparent and well-justified.

The Code emphasizes the responsibilities of shareholders, boards of directors, and management in achieving effective governance. It covers key areas such as board composition, nomination processes, the division of roles between boards and executives, risk management, remuneration policies, and sustainability reporting. Specific provisions mandate the establishment of nomination committees, annual evaluations of boards and CEOs, and clear rules on information disclosure and remuneration. The Code also incorporates requirements from EU directives, including shareholder rights and non-financial information disclosure.

By aligning with international governance standards and EU regulations, the Code supports harmonization within Nordic and European markets. It enhances investor confidence, competitiveness, and the sustainable development of Swedish-listed companies.', 'The Swedish Corporate Governance Code, updated and effective as of December 1, 2016, establishes a framework for good corporate governance practices in listed companies on regulated markets in Sweden. It aims to foster trust in Swedish companies by promoting transparency, accountability, and long-term value creation while maintaining flexibility through the "comply or explain" principle. Companies must disclose adherence to the Code’s provisions or provide explanations for deviations, ensuring that alternative approaches are transparent and well-justified.

The Code emphasizes the responsibilities of shareholders, boards of directors, and management in achieving effective governance. It covers key areas such as board composition, nomination processes, the division of roles between boards and executives, risk management, remuneration policies, and sustainability reporting. Specific provisions mandate the establishment of nomination committees, annual evaluations of boards and CEOs, and clear rules on information disclosure and remuneration. The Code also incorporates requirements from EU directives, including shareholder rights and non-financial information disclosure.

By aligning with international governance standards and EU regulations, the Code supports harmonization within Nordic and European markets. It enhances investor confidence, competitiveness, and the sustainable development of Swedish-listed companies.', 'Sweden', 'climate', 'in_force', '2016-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_1', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b15b286d-e302-53ba-9f44-7155e91c9730', 'Sweden Sustainable Business Guide - the Government''s policy', 'Sustainable Business Guide - the Government''s policy for sustainable business', 'On the basis of the Government’s Communication on sustainable business, they have presented their expectations, views and actions for sustainable business. They have also brought together practical advice and tools for companies seeking to develop their sustainable business efforts. The primary target group is Swedish companies – large, medium-sized and small – as well as other groups interested in sustainable business.', 'On the basis of the Government’s Communication on sustainable business, they have presented their expectations, views and actions for sustainable business. They have also brought together practical advice and tools for companies seeking to develop their sustainable business efforts. The primary target group is Swedish companies – large, medium-sized and small – as well as other groups interested in sustainable business.', 'On the basis of the Government’s Communication on sustainable business, they have presented their expectations, views and actions for sustainable business. They have also brought together practical advice and tools for companies seeking to develop their sustainable business efforts. The primary target group is Swedish companies – large, medium-sized and small – as well as other groups interested in sustainable business.', 'Sweden', 'climate', 'in_force', '2016-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_5', ARRAY['sdg13', 'other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dc9e7ee4-e129-5b03-ad35-c99725a688c5', 'Sweden Action Plan on Business and Human Rights', 'Action Plan on Business and Human Rights', 'The national action plan aims to translate the UN Guiding Principles into practical action at national level. The plan responds to the European Commission’s request that Member States draw up national action plans.', 'The national action plan aims to translate the UN Guiding Principles into practical action at national level. The plan responds to the European Commission’s request that Member States draw up national action plans.', 'The national action plan aims to translate the UN Guiding Principles into practical action at national level. The plan responds to the European Commission’s request that Member States draw up national action plans.', 'Sweden', 'governance', 'in_force', '2015-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_3', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('190f480c-d0b0-5493-b49c-1eb0d1faf9de', 'Sweden Companies'' reporting on sustainability and diversity policy', 'Companies'' reporting on sustainability and diversity policy', 'The 2014 Swedish government report, Ds 2014:45, outlines proposed amendments to corporate disclosure requirements, aligning with EU Directive 2014/95/EU. The directive mandates large public-interest entities with over 500 employees to report non-financial information and diversity policies as part of their annual management reports. The proposals aim to enhance corporate accountability, promote sustainable practices, and ensure transparency regarding environmental, social, and governance (ESG) matters.

Key disclosure areas include:

Environmental impacts and climate-related risks.

Social and employee-related issues, including human rights.

Anti-corruption and bribery measures.

Diversity policies on boards of directors, emphasizing gender, age, education, and professional background.

Companies must provide information on policies, implementation, and outcomes or explain the absence of such policies (“comply or explain”). The proposals also align reporting standards with international frameworks such as the UN Global Compact and OECD Guidelines.', 'The 2014 Swedish government report, Ds 2014:45, outlines proposed amendments to corporate disclosure requirements, aligning with EU Directive 2014/95/EU. The directive mandates large public-interest entities with over 500 employees to report non-financial information and diversity policies as part of their annual management reports. The proposals aim to enhance corporate accountability, promote sustainable practices, and ensure transparency regarding environmental, social, and governance (ESG) matters.

Key disclosure areas include:

Environmental impacts and climate-related risks.

Social and employee-related issues, including human rights.

Anti-corruption and bribery measures.

Diversity policies on boards of directors, emphasizing gender, age, education, and professional background.

Companies must provide information on policies, implementation, and outcomes or explain the absence of such policies (“comply or explain”). The proposals also align reporting standards with international frameworks such as the UN Global Compact and OECD Guidelines.', 'The 2014 Swedish government report, Ds 2014:45, outlines proposed amendments to corporate disclosure requirements, aligning with EU Directive 2014/95/EU. The directive mandates large public-interest entities with over 500 employees to report non-financial information and diversity policies as part of their annual management reports. The proposals aim to enhance corporate accountability, promote sustainable practices, and ensure transparency regarding environmental, social, and governance (ESG) matters.

Key disclosure areas include:

