INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f66d6df9-5a2d-56d8-9526-c353cd2e3646', 'Sweden external reporting by state-owned companies', 'Guidelines for external reporting by state-owned companies', 'The Government adopted these guidelines for external reporting by state-owned companies on 29 November 2007. They replace the previous guidelines which were adopted in 2002. The guidelines have been complemented with expanded and clearer requirements on information about sustainability.', 'The Government adopted these guidelines for external reporting by state-owned companies on 29 November 2007. They replace the previous guidelines which were adopted in 2002. The guidelines have been complemented with expanded and clearer requirements on information about sustainability.', 'The Government adopted these guidelines for external reporting by state-owned companies on 29 November 2007. They replace the previous guidelines which were adopted in 2002. The guidelines have been complemented with expanded and clearer requirements on information about sustainability.', 'Sweden', 'climate', 'in_force', '2007-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_2', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'sdg16', 'sdg12', 'sweden', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
