INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('759ec96c-8456-5adb-8751-0ca0620cbf4c', 'Sweden NBK Recommendations', 'The NBK Recommendations', 'New Takeover Recommendations were adopted in January 2003, following an extensive review. These Recommendations apply as from 1 March 2003. In view of the key role played by the NBK Takeover Recommendations in the Swedish self-regulation process, we have considered that publication of a new edition of English translations of all the current Recommendations is desirable.', 'New Takeover Recommendations were adopted in January 2003, following an extensive review. These Recommendations apply as from 1 March 2003. In view of the key role played by the NBK Takeover Recommendations in the Swedish self-regulation process, we have considered that publication of a new edition of English translations of all the current Recommendations is desirable.', 'New Takeover Recommendations were adopted in January 2003, following an extensive review. These Recommendations apply as from 1 March 2003. In view of the key role played by the NBK Takeover Recommendations in the Swedish self-regulation process, we have considered that publication of a new edition of English translations of all the current Recommendations is desirable.', 'Sweden', 'governance', 'in_force', '2003-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_11', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg16', 'sweden', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('94a85c08-4c9d-5136-a68b-75dd4d3bd3b8', 'Sweden Corporate Governance Policy', 'Corporate Governance Policy, 2001', 'This document is a a new policy that represents an augmentation and tightening up on a number of issnes compared with the Guidelines for better control and insight into companies quoted on the stockmarket that the Swedish Shareholders’ Association presented in March 1993.', 'This document is a a new policy that represents an augmentation and tightening up on a number of issnes compared with the Guidelines for better control and insight into companies quoted on the stockmarket that the Swedish Shareholders’ Association presented in March 1993.', 'This document is a a new policy that represents an augmentation and tightening up on a number of issnes compared with the Guidelines for better control and insight into companies quoted on the stockmarket that the Swedish Shareholders’ Association presented in March 1993.', 'Sweden', 'governance', 'in_force', '2001-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_7', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bd2595ba-88a0-5e5a-ab2f-d6b4fb499ef0', 'Sweden Swedish Environmental Code (1998:808)', 'Swedish Environmental Code (1998:808)', 'The Swedish Environmental Code, enacted in 1998, consolidates and updates previous environmental legislation to establish a comprehensive framework for environmental protection and sustainable development in Sweden. The Code applies broadly to individuals, businesses, and public authorities, covering areas such as land and water management, pollution control, nature conservation, and sustainable use of natural resources. Its core principles include the precautionary principle, polluter pays principle, and sustainable development as foundational goals.

Key provisions of the Code address:

Environmental impact assessments (EIA) for activities with significant environmental effects.

Permitting systems for industrial activities and resource extraction.

Safeguards for biodiversity and natural habitats.

Public participation in environmental decision-making processes.

The Code aligns with European Union environmental directives and international agreements, ensuring Swedish environmental governance meets global standards. It promotes transparency and accountability, requiring comprehensive reporting and adherence to strict environmental standards.', 'The Swedish Environmental Code, enacted in 1998, consolidates and updates previous environmental legislation to establish a comprehensive framework for environmental protection and sustainable development in Sweden. The Code applies broadly to individuals, businesses, and public authorities, covering areas such as land and water management, pollution control, nature conservation, and sustainable use of natural resources. Its core principles include the precautionary principle, polluter pays principle, and sustainable development as foundational goals.

Key provisions of the Code address:

Environmental impact assessments (EIA) for activities with significant environmental effects.

Permitting systems for industrial activities and resource extraction.

Safeguards for biodiversity and natural habitats.

Public participation in environmental decision-making processes.

The Code aligns with European Union environmental directives and international agreements, ensuring Swedish environmental governance meets global standards. It promotes transparency and accountability, requiring comprehensive reporting and adherence to strict environmental standards.', 'The Swedish Environmental Code, enacted in 1998, consolidates and updates previous environmental legislation to establish a comprehensive framework for environmental protection and sustainable development in Sweden. The Code applies broadly to individuals, businesses, and public authorities, covering areas such as land and water management, pollution control, nature conservation, and sustainable use of natural resources. Its core principles include the precautionary principle, polluter pays principle, and sustainable development as foundational goals.

