INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('68fd45e3-0c8a-5544-88c6-d5de2380bc61', 'Switzerland Reponsible Business Initiative Swiss Coalition for Corporate Justice', 'The Reponsible Business Initiative Swiss Coalition for Corporate Justice (SCCJ)', 'Under the Responsible Business Initiative, companies would have been legally obliged to incorporate respect for human rights and the environment in all their business activities. This mandatory due diligence would also have been applied to Swiss based companies’ activities abroad.', 'Under the Responsible Business Initiative, companies would have been legally obliged to incorporate respect for human rights and the environment in all their business activities. This mandatory due diligence would also have been applied to Swiss based companies’ activities abroad.', 'Under the Responsible Business Initiative, companies would have been legally obliged to incorporate respect for human rights and the environment in all their business activities. This mandatory due diligence would also have been applied to Swiss based companies’ activities abroad.', 'Switzerland', 'governance', 'in_force', '2020-01-01'::date, 'Switzerland', 'https://www.carrotsandsticks.org/policies/172_11', ARRAY['other sustainability policy', 'mandatory', 'switzerland', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
