INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('725337cf-8eff-533a-b5ef-f98dee13d47f', 'Switzerland Protection against Dangerous Substances and Preparations (Chemicals Ordinance', 'Ordinance on Protection against Dangerous Substances and Preparations (Chemicals Ordinance, ChemO)', 'This Ordinance regulates the determination and assessment of dangers and risks that substances and preparations may pose to human life and health and to the environment; the conditions under which substances and preparations that may endanger people or the environment are placed on the market; the handling of substances and preparations that may endanger people or the environment and the way in which data relating to substances and preparations is processed by the enforcement authorities.', 'This Ordinance regulates the determination and assessment of dangers and risks that substances and preparations may pose to human life and health and to the environment; the conditions under which substances and preparations that may endanger people or the environment are placed on the market; the handling of substances and preparations that may endanger people or the environment and the way in which data relating to substances and preparations is processed by the enforcement authorities.', 'This Ordinance regulates the determination and assessment of dangers and risks that substances and preparations may pose to human life and health and to the environment; the conditions under which substances and preparations that may endanger people or the environment are placed on the market; the handling of substances and preparations that may endanger people or the environment and the way in which data relating to substances and preparations is processed by the enforcement authorities.', 'Switzerland', 'governance', 'in_force', '2016-01-01'::date, 'Switzerland', 'https://www.carrotsandstic