INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('35b75ede-6098-5995-be82-980ef0162429', 'Switzerland Federal Act on the Protection of the Environment', 'Federal Act on the Protection of the Environment (Environmental Protection Act, EPA)', 'This Act is intended to protect people, animals and plants, their biological communities and habitats against harmful effects or nuisances and to preserve the natural foundations of life sustainably, in particular biological diversity and the fertility of the soil.', 'This Act is intended to protect people, animals and plants, their biological communities and habitats against harmful effects or nuisances and to preserve the natural foundations of life sustainably, in particular biological diversity and the fertility of the soil.', 'This Act is intended to protect people, animals and plants, their biological communities and habitats against harmful effects or nuisances and to preserve the natural foundations of life sustainably, in particular biological diversity and the fertility of the soil.', 'Switzerland', 'nature', 'in_force', '2016-01-01'::date, 'Switzerland', 'https://www.carrotsandsticks.org/policies/172_30', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'switzerland', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('696f3d92-3676-5346-b7cf-ac8ed69c4b19', 'Switzerland Swiss Code of Best Practice for Corporate Governance', 'Swiss Code of Best Practice for Corporate Governance, 2016', 'The purpose of the “Swiss Code” is to set out guidelines and recommendations. However, it should not force Swiss companies into a straitjacket. Every company should retain the option of putting its own ideas on organising corporate governance into practice.', 'The purpose of the “Swiss Code” is to set out guidelines and recommendations. However, it should not force Swiss companies into a straitjacket. Every company should retain the option of putting its own ideas on organising corporate governance into practice.', 'The purpose of the “Swiss Code” is to set out guidelines and recommendations. However, it should not force Swiss companies into a straitjacket. Every company should retain the option of putting its own ideas on organising corporate governance into practice.', 'Switzerland', 'governance', 'in_force', '2016-01-01'::date, 'Switzerland', 'https://www.carrotsandsticks.org/policies/172_7', ARRAY['regulations', 'switzerland', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
