INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4f0f79c1-adfc-5b7f-83ff-0f117297b8fb', 'Switzerland institutional investors governing the exercising of participation rights', 'Guidelines for institutional investors governing the exercising of participation rights in public limited companies', 'These guidelines govern the exercising of participation rights in Swiss listed companies. However, some of the principles may also be applied where appropriate as the basis for the exercising of participation rights in foreign or non-listed companies or organisations (including those with a legal form other than that of public limited company).', 'These guidelines govern the exercising of participation rights in Swiss listed companies. However, some of the principles may also be applied where appropriate as the basis for the exercising of participation rights in foreign or non-listed companies or organisations (including those with a legal form other than that of public limited company).', 'These guidelines govern the exercising of participation rights in Swiss listed companies. However, some of the principles may also be applied where appropriate as the basis for the exercising of participation rights in foreign or non-listed companies or organisations (including those with a legal form other than that of public limited company).', 'Switzerland', 'governance', 'in_force', '2013-01-01'::date, 'Switzerland', 'https://www.carrotsandsticks.org/policies/172_6', ARRAY['guidance_frameworks', 'voluntary', 'switzerland', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
